<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Personal Expense Tracker</title>
<style>
  :root{
    --bg:#f3f4f6;
    --card:#ffffff;
    --ink:#111827;
    --muted:#6b7280;
    --line:#e5e7eb;
    --accent:#2563eb;
    --accent-dark:#1d4ed8;
    --danger:#dc2626;
  }
  *{box-sizing:border-box}
  html,body{margin:0}
  body{
    background:var(--bg);
    color:var(--ink);
    font-family:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
    font-size:15px;
    line-height:1.5;
  }
  .wrap{max-width:860px;margin:0 auto;padding:28px 16px 72px}
  h1{font-size:1.55rem;margin:0 0 4px}
  .subtitle{color:var(--muted);margin:0 0 22px;font-size:.92rem}
  .card{
    background:var(--card);
    border:1px solid var(--line);
    border-radius:12px;
    padding:18px 20px;
    margin-bottom:18px;
    box-shadow:0 1px 2px rgba(17,24,39,.05);
  }
  .card h2{
    font-size:.78rem;letter-spacing:.08em;text-transform:uppercase;
    color:var(--muted);margin:0 0 14px;font-weight:700;
  }

  /* --- form & inputs --- */
  #expense-form{display:flex;flex-wrap:wrap;gap:14px;align-items:flex-end}
  .filters-row{display:flex;flex-wrap:wrap;gap:14px;align-items:flex-end}
  .field{display:flex;flex-direction:column;gap:5px}
  .field .lbl{font-size:.76rem;font-weight:600;color:var(--muted)}
  input,select{
    font:inherit;color:inherit;
    padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:#fff;
  }
  input:focus,select:focus{outline:2px solid var(--accent);outline-offset:1px;border-color:var(--accent)}
  #amount{width:130px}
  #note{width:230px}
  button{font:inherit;cursor:pointer;border:none;border-radius:8px}
  .btn-primary{background:var(--accent);color:#fff;padding:9px 18px;font-weight:600}
  .btn-primary:hover{background:var(--accent-dark)}
  .btn-ghost{background:#fff;border:1px solid var(--line);padding:8px 14px;color:var(--ink)}
  .btn-ghost:hover{border-color:var(--muted)}
  #form-error{color:var(--danger);font-weight:600;margin:12px 0 0;font-size:.9rem}
  #form-error:empty{display:none}

  /* --- summary --- */
  .grand-total{margin:0;font-size:1rem}
  .grand-total strong{font-size:1.5rem;font-variant-numeric:tabular-nums;margin-left:4px}
  .cat-summary{list-style:none;display:flex;flex-wrap:wrap;gap:8px;margin:12px 0 0;padding:0}
  .cat-total{
    background:#eef2ff;border:1px solid #dbe3ff;color:#3730a3;
    border-radius:999px;padding:4px 12px;font-size:.85rem;font-variant-numeric:tabular-nums;
  }

  /* --- expense list --- */
  #expense-list{margin-top:2px}
  .expense{
    display:flex;flex-wrap:wrap;gap:6px 14px;align-items:center;
    padding:10px 4px;border-bottom:1px solid var(--line);
  }
  .expense:last-child{border-bottom:none}
  .exp-date,.exp-cat{color:var(--muted);font-size:.88rem;font-variant-numeric:tabular-nums}
  .exp-note{flex:1 1 140px;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
  .exp-amt{margin-left:auto;font-weight:600;font-variant-numeric:tabular-nums}
  .exp-del{
    background:#fee2e2;color:var(--danger);
    padding:5px 11px;font-size:.8rem;font-weight:600;border-radius:6px;
  }
  .exp-del:hover{background:var(--danger);color:#fff}
  #list-empty{color:var(--muted);font-style:italic;margin:10px 0 0}
  [hidden]{display:none!important}
</style>
</head>
<body>
<div class="wrap">
  <h1>Expense Tracker</h1>
  <p class="subtitle">Track your spending, filter by category and date range. Everything is saved in your browser.</p>

  <!-- Entry form -->
  <section class="card" aria-labelledby="add-heading">
    <h2 id="add-heading">Add expense</h2>
    <form id="expense-form" novalidate autocomplete="off">
      <label class="field">
        <span class="lbl">Amount</span>
        <input id="amount" type="number" step="any" min="0" placeholder="0.00" inputmode="decimal">
      </label>
      <label class="field">
        <span class="lbl">Category</span>
        <select id="category">
          <option value="groceries">groceries</option>
          <option value="transport">transport</option>
          <option value="bills">bills</option>
          <option value="fun">fun</option>
        </select>
      </label>
      <label class="field">
        <span class="lbl">Date</span>
        <input id="date" type="date">
      </label>
      <label class="field">
        <span class="lbl">Note (optional)</span>
        <input id="note" type="text" maxlength="120" placeholder="e.g. weekly shop">
      </label>
      <button type="submit" id="add-expense" class="btn-primary">Add expense</button>
    </form>
    <p id="form-error" role="alert"></p>
  </section>

  <!-- Filters -->
  <section class="card" aria-labelledby="filters-heading">
    <h2 id="filters-heading">Filters</h2>
    <div class="filters-row">
      <label class="field">
        <span class="lbl">Category</span>
        <select id="filter-category">
          <option value="all">all</option>
          <option value="groceries">groceries</option>
          <option value="transport">transport</option>
          <option value="bills">bills</option>
          <option value="fun">fun</option>
        </select>
      </label>
      <label class="field">
        <span class="lbl">From</span>
        <input id="filter-from" type="date">
      </label>
      <label class="field">
        <span class="lbl">To</span>
        <input id="filter-to" type="date">
      </label>
      <button type="button" id="clear-filters" class="btn-ghost">Clear filters</button>
    </div>
  </section>

  <!-- Summary -->
  <section class="card" aria-labelledby="summary-heading">
    <h2 id="summary-heading">Summary of visible expenses</h2>
    <p class="grand-total">Total:<strong id="total">0.00</strong></p>
    <ul class="cat-summary">
      <li class="cat-total" data-cat="groceries">groceries: 0.00</li>
      <li class="cat-total" data-cat="transport">transport: 0.00</li>
      <li class="cat-total" data-cat="bills">bills: 0.00</li>
      <li class="cat-total" data-cat="fun">fun: 0.00</li>
    </ul>
  </section>

  <!-- List -->
  <section class="card" aria-labelledby="list-heading">
    <h2 id="list-heading">Expenses (newest first)</h2>
    <div id="expense-list"></div>
    <p id="list-empty" hidden>No expenses yet.</p>
  </section>
</div>

<script>
(function () {
  'use strict';

  var CATEGORIES = ['groceries', 'transport', 'bills', 'fun'];
  var STORAGE_KEY = 'personal-expense-tracker.v1';

  function $(sel) { return document.querySelector(sel); }

  var els = {
    form: $('#expense-form'),
    amount: $('#amount'),
    category: $('#category'),
    date: $('#date'),
    note: $('#note'),
    formError: $('#form-error'),
    list: $('#expense-list'),
    empty: $('#list-empty'),
    total: $('#total'),
    filterCategory: $('#filter-category'),
    filterFrom: $('#filter-from'),
    filterTo: $('#filter-to'),
    clearFilters: $('#clear-filters')
  };

  var expenses = [];

  /* ---------- persistence ---------- */

  function uid() {
    return 'x' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  function loadExpenses() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed
        .filter(function (e) {
          return e && typeof e === 'object' &&
            typeof e.amount === 'number' && isFinite(e.amount) &&
            typeof e.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(e.date);
        })
        .map(function (e) {
          return {
            id: String(e.id || uid()),
            amount: e.amount,
            category: CATEGORIES.indexOf(e.category) !== -1 ? e.category : 'fun',
            date: e.date,
            note: typeof e.note === 'string' ? e.note : ''
          };
        });
    } catch (err) {
      return [];
    }
  }

  function saveExpenses() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
    } catch (err) { /* storage unavailable: app still works in-memory */ }
  }

  /* ---------- filtering ---------- */

  function matchesFilters(exp) {
    var fc = els.filterCategory.value;
    if (fc !== 'all' && exp.category !== fc) return false;
    var from = els.filterFrom.value;
    if (from && exp.date < from) return false;
    var to = els.filterTo.value;
    if (to && exp.date > to) return false;
    return true;
  }

  /* ---------- rendering ---------- */

  function buildRow(exp) {
    var row = document.createElement('div');
    row.className = 'expense';
    row.dataset.id = exp.id;

    var d = document.createElement('span');
    d.className = 'exp-date';
    d.textContent = exp.date;

    var c = document.createElement('span');
    c.className = 'exp-cat';
    c.textContent = exp.category;

    var n = document.createElement('span');
    n.className = 'exp-note';
    n.textContent = exp.note;

    var a = document.createElement('span');
    a.className = 'exp-amt';
    a.textContent = exp.amount.toFixed(2);

    var del = document.createElement('button');
    del.type = 'button';
    del.className = 'exp-del';
    del.textContent = 'Delete';
    del.setAttribute('aria-label', 'Delete expense of ' + exp.amount.toFixed(2));
    del.addEventListener('click', function () { removeExpense(exp.id); });

    row.appendChild(d);
    row.appendChild(c);
    row.appendChild(n);
    row.appendChild(a);
    row.appendChild(del);
    return row;
  }

  function render() {
    // Newest first: later date first; same date -> most recently added first.
    var indices = expenses.map(function (_, i) { return i; });
    indices.sort(function (a, b) {
      var da = expenses[a].date, db = expenses[b].date;
      if (da !== db) return da < db ? 1 : -1;
      return b - a;
    });

    els.list.textContent = '';

    var total = 0;
    var visibleCount = 0;
    var catTotals = {};
    CATEGORIES.forEach(function (c) { catTotals[c] = 0; });

    indices.forEach(function (i) {
      var exp = expenses[i];
      var row = buildRow(exp);
      if (matchesFilters(exp)) {
        total += exp.amount;
        catTotals[exp.category] += exp.amount;
        visibleCount++;
      } else {
        row.style.display = 'none';
      }
      els.list.appendChild(row);
    });

    els.total.textContent = total.toFixed(2);

    Array.prototype.forEach.call(document.querySelectorAll('.cat-total'), function (el) {
      var c = el.getAttribute('data-cat');
      el.textContent = c + ': ' + (catTotals[c] || 0).toFixed(2);
    });

    if (expenses.length === 0) {
      els.empty.textContent = 'No expenses yet \u2014 add your first one above.';
      els.empty.hidden = false;
    } else if (visibleCount === 0) {
      els.empty.textContent = 'No expenses match the current filters.';
      els.empty.hidden = false;
    } else {
      els.empty.hidden = true;
    }
  }

  /* ---------- actions ---------- */

  function removeExpense(id) {
    expenses = expenses.filter(function (e) { return e.id !== id; });
    saveExpenses();
    render();
  }

  function handleSubmit(ev) {
    ev.preventDefault();

    var rawAmount = els.amount.value.trim();
    var amount = Number(rawAmount);
    if (rawAmount === '' || !isFinite(amount) || amount <= 0) {
      els.formError.textContent = 'Please enter a valid amount greater than zero.';
      els.amount.focus();
      return;
    }
    if (els.date.value === '') {
      els.formError.textContent = 'Please pick a date for this expense.';
      els.date.focus();
      return;
    }

    expenses.push({
      id: uid(),
      amount: Math.round(amount * 100) / 100,
      category: els.category.value,
      date: els.date.value,
      note: els.note.value.trim()
    });
    saveExpenses();

    els.formError.textContent = '';   // clear any previous error
    els.amount.value = '';            // reset the amount field
    render();
  }

  /* ---------- init ---------- */

  expenses = loadExpenses();

  els.form.addEventListener('submit', handleSubmit);

  [els.filterCategory, els.filterFrom, els.filterTo].forEach(function (el) {
    el.addEventListener('change', render);
    el.addEventListener('input', render);
  });

  els.clearFilters.addEventListener('click', function () {
    els.filterCategory.value = 'all';
    els.filterFrom.value = '';
    els.filterTo.value = '';
    render();
  });

  render();
})();
</script>
</body>
</html>
